      "highlights": [
        {
          "text": "had missed the first lecture",
          "note": "過去完成表示在另一事件（解釋）之前就已經發生的動作"
        },
        {
          "text": "weren't sure whether they were supposed to submit a draft by Friday",
          "note": "表示不確定（被期待要做的事）和截止時間"
        }
      ],
      "vocab": [
        {
          "term": "assignment",
          "inSentence": "assignment",
          "kind": "word",
          "pos": "n.",
          "zh": "作業；指定的任務",
          "ipa": "/əˈsaɪnmənt/",
          "collocations": [
            "homework assignment",
            "complete an assignment"
          ]
        ,
          "examples": [
            {
              "en": "She turned in the assignment on time.",
              "zh": "她準時交了作業。"
            }
          ]
        },
        {
          "term": "draft",
          "inSentence": "draft",
          "kind": "word",
          "pos": "n.",
          "zh": "草稿、初稿",
          "ipa": "/dræft/",
          "collocations": [
            "first draft",
            "revise a draft"
          ],
          "examples": [
            {
              "en": "Please send me the draft before we meet.",
              "zh": "請在開會前把草稿寄給我。"
            }
          ]
        },
        {
          "term": "be supposed to",
          "inSentence": "were supposed to submit",
          "kind": "phrase",
          "pos": "phr.",
          "zh": "應該（被期望去做某事）",
          "ipa": "/bɪ səˈpoʊzd tu/",
          "collocations": [
            "be supposed to do",
            "supposed to arrive"
          ],
          "examples": [
            {
              "en": "You're supposed to wear a suit to the interview.",
              "zh": "面試時你應該穿西裝。"
            }
          ]
        }
      ],
      "grammar": [
        {
          "point": "past perfect",
          "quote": "had explained / had missed",
          "explanation": "past perfect 用來表示在過去另一個時間或事件之前已經發生的動作，這句表示教授在講座前已經解釋過，學生在更早之前就錯過了第一堂課。",
          "examples": [
            {
              "en": "She had left before I arrived.",
              "zh": "我到之前她已經離開了。"
            }
          ],
          "pitfall": "學生常把 past perfect 和 simple past 混用；若有兩個過去動作，要明確用 past perfect 表示較早發生的那個。"
        },
        {
          "point": "polite uncertainty with 'whether'",
          "quote": "weren't sure whether they were supposed to submit",
          "explanation": "'whether' 用來引出兩種可能（要不要做），在禮貌或正式寫法中很常見，後面可接從句。",
          "examples": [
            {
              "en": "I don't know whether I should call him.",
              "zh": "我不知道是否應該打給他。"
            }
          ],
          "pitfall": "不要用 'if' 在正式寫作中替換 'whether'（某些情況下可用，但 'whether' 更清楚）。"
        }
      ],
      "chunks": [
        {
          "text": "Although the professor",
          "role": "connector",
          "zh": "雖然教授"
        },
        {
          "text": "had explained the assignment twice,",
          "role": "main",
          "zh": "已經解釋過那份作業兩次，"
        },
        {
          "text": "several students",
          "role": "main",
          "zh": "幾位學生"
        },
        {
          "text": "who had missed the first lecture",
          "role": "subordinate",
          "zh": "（那些）錯過第一堂課的"
        },
        {
          "text": "still weren't sure",
          "role": "main",
          "zh": "仍然不確定"
        },
        {
          "text": "whether they were supposed to submit a draft by Friday.",
          "role": "subordinate",
          "zh": "是否應該在星期五之前提交一份草稿。"
        }
      ],
      "connected": [
        {
          "text": "had explained the",
          "soundsLike": "hæd ɪkˈspleɪnd ðə",
          "note": "'the' 在連讀中常弱讀為 /ðə/，且 past tense 'explained' 的 /d/ 與下一個 /ð/ 幾乎連在一起，聽起來像一段連續音。"
        },
        {
          "text": "were supposed to submit",
          "soundsLike": "wər səˈpoʊzd tə səbˈmɪt",
          "note": "'to' 在口語中常弱讀為 /tə/，連在 submit 前使得整片段快而緊湊，容易聽成 'səˈpoʊzdə'."
        },
        {
          "text": "missed the first",
          "soundsLike": "mɪst ðə fɝst",
          "note": "'t' 往往輕弱，且 'the first' 連讀成一個流暢片段，'the' 弱讀為 /ðə/。"
        }
      ]
    }
  ]
}
